insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-209', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Among carbon, nitrogen, oxygen and fluorine, the most negative electron gain enthalpy is that of', '["carbon","nitrogen","oxygen","fluorine"]'::jsonb, 3, 'Fluorine is one electron short of neon and, despite the F/Cl anomaly, is still the most exothermic of this period-2 set.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'electron-gain') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
